// Contenido del popup para cada feature
function popupContentRegiones(feature) {
    return (
        "<div id='Estilo1'><h3>DETALLE</h3></div>" +
        "<hr class='hrx' style='color: #ef7d26;' align='left' noshade='noshade' size='0.5' width='100%' />" +
        "<div id='Estilo3a'>" +
        "<b> PROVINCIA : </b>" + feature.properties.PROVINCIA + "<br>" +
        "<b> REGION : </b>" + feature.properties.region + "<br>" +
        
        "<br>" +

        "</div>"
    );
}

function getColorRegiones(region) {
    switch (region) {
        case 'NOA':
            return '#FF9D21';
        case 'NEA':
            return '#5650C4';
        case 'CUYO':
            return '#FF729B';
        case 'PATAGONIA':
            return '#F9372D';
        case 'CENTRO':
            return '#6DC282';
        case 'BSAS':
            return '#35C0BA';
        default:
            return '';
    }
}
function styleRegiones(feature) {
    return {
        fillColor: getColorRegiones(feature.properties.region),
        weight: 1,
        opacity: 0.9,
        color: '#292828',
        dashArray: '0',
        fillOpacity: 0.9,
        stroke: '#232323',


    }
}
// Función para generar la leyenda
function createLegendRegiones() {
    var legend = L.control({ position: 'bottomright' });

    legend.onAdd = function () {
        var div = L.DomUtil.create('div', 'info legend');
        var labels = [];

        // Array con los estilos y sus etiquetas correspondientes
        var styles = [
            { label: 'NOA', color: '#FF9D21' },
            { label: 'NEA', color: '#5650C4' },
            { label: 'CUYO', color: '#FF729B' },
            { label: 'CENTRO', color: '#6DC282' },
            { label: 'PATAGONIA', color: '#F9372D' },
            { label: 'BUENOS AIRES', color:'#35C0BA' },

            // Agrega aquí el resto de estilos con su respectiva etiqueta y color
        ];

        // Genera el contenido HTML de la leyenda
        styles.forEach(function (style) {
            labels.push(
                '<i style="background:' + style.color + '"></i> ' + style.label
            );
        });

        div.innerHTML = labels.join('<br>');
        return div;
    };

    // Función para mostrar/ocultar la leyenda
    function toggleLegend() {
        if (map.hasLayer(REFIONESFAO)) {
            legend.addTo(map);
        } else {
            legend.remove();
        }
    }
    // Eliminar la leyenda al inicio
    legend.remove();
    // Escucha el cambio de estado de la capa
    map.on('overlayadd overlayremove', toggleLegend);
}


